def check_cube(n):
    if n < 0:
        return round((-n**(1/3)))**3 - n
    return round(n**(1/3))**3 - n

def solve_diophantine():
    # We are checking n^3 = 8m^3 - 5, or 8m^3 - n^3 = 5
    print("Checking small values for m:")
    for m in range(-10, 11):
        val = 8 * (m**3) - 5

        # Check if val is a perfect cube
        cbrt_val = round(val**(1/3))
        is_cube = (cbrt_val**3 == val)

        if is_cube:
            print(f"Found solution for m={m}: 8*({m})^3 - 5 = {val} = ({cbrt_val})^3. This corresponds to k = m^3.")

        # Also check constraints for m (k=m^3 must satisfy 5 \nmid k and k \not\equiv 12 \pmod{13})
        if m % 5 == 0:
             print(f"m={m} skipped due to constraint 5|k.")
        else:
             k_mod_13 = (m**3) % 13
             if k_mod_13 == 12:
                 print(f"m={m} skipped due to constraint k \equiv 12 (mod 13).")


